-- Run this once in the Supabase SQL editor (Dashboard -> SQL Editor).
-- Ids are UUIDs generated by the app, so /api/sync can safely upsert.

create table if not exists public.farmers (
  id            uuid primary key,
  name          text not null,
  phone         text not null unique,
  village       text,
  farm_size_ha  numeric,
  created_at    timestamptz not null default now()
);

create table if not exists public.trials (
  id               uuid primary key,
  farmer_id        uuid not null references public.farmers(id) on delete cascade,
  crop             text not null,
  variety          text,
  treatment        text,
  planting_date    date,
  yield_kg_per_ha  numeric not null check (yield_kg_per_ha >= 0),
  notes            text,
  created_at       timestamptz not null default now()
);

create index if not exists trials_crop_idx on public.trials (crop);
create index if not exists trials_farmer_idx on public.trials (farmer_id);

-- Row Level Security: ON by default for safety. Pick ONE of the options below.
alter table public.farmers enable row level security;
alter table public.trials  enable row level security;

-- Option A (recommended): use the service-role key in SUPABASE_KEY on your
-- server only. The service role bypasses RLS, so no policies are needed.
-- Never put the service-role key in browser code.

-- Option B (quick prototype only): allow the anon key to read/write.
-- Uncomment, and remove before going live.
-- create policy "proto all farmers" on public.farmers for all using (true) with check (true);
-- create policy "proto all trials"  on public.trials  for all using (true) with check (true);
